content.text:
请对以下 case 进行三维加权评分。

=== case_id ===
Case-03-anti-addiction-010

=== 用户原始指令 (query.txt) ===
主体是图的防沉迷卡，数字会变，点进系统操作，能读天气

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "主体是图的防沉迷卡，数字会变，点进系统操作，能读天气",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "parent_control"
      }
    }
  ],
  "dataModelSchema": {
    "antiAddiction": {
      "appName": {
        "type": "string",
        "description": "当前受防沉迷管理的应用名称",
        "sampleValue": "短视频"
      },
      "usedMinutesText": {
        "type": "string",
        "description": "今日已使用时长展示文本，随系统健康使用数据变化",
        "sampleValue": "42"
      },
      "limitText": {
        "type": "string",
        "description": "今日使用时长限制展示文本",
        "sampleValue": "60分钟上限"
      },
      "statusText": {
        "type": "string",
        "description": "当前防沉迷状态提示",
        "sampleValue": "剩余18分钟"
      }
    },
    "data": {
      "weather": {
        "location": {
          "districtName": {
            "type": "string",
            "description": "天气查询的区县名称",
            "sampleValue": "朝阳区"
          }
        },
        "current": {
          "temperatureText": {
            "type": "string",
            "description": "当前温度展示文本",
            "sampleValue": "27°C"
          },
          "condition": {
            "type": "string",
            "description": "当前天气现象",
            "sampleValue": "多云"
          },
          "airQuality": {
            "type": "string",
            "description": "当前空气质量等级",
            "sampleValue": "良"
          }
        }
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/icon_tiktok.png",
      "description": "防沉迷场景的短视频应用图标素材，适合作为卡片主体图形。"
    },
    {
      "src": "resources/base/media/icon_timing.png",
      "description": "防沉迷场景的计时图标素材，适合表达使用时长和限制。"
    },
    {
      "src": "resources/base/media/cloudy.png",
      "description": "彩色云朵天气图标素材，适合展示当前多云天气摘要。"
    }
  ]
}

